module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Compare each bit with 100ns delay
    wire [3:0] Y;

    assign #100 Y[0] = (A[0] > B[0]);
    assign #100 Y[1] = (A[1] > B[1]);
    assign #100 Y[2] = (A[2] > B[2]);
    assign #100 Y[3] = (A[3] > B[3]);

    // Generate group outputs by ANDing respective bits
    assign A_greater = &Y;    // All A bits greater than B
    assign A_equal   = &(~Y | ~B); // At least one bit equal
    assign A_less    = &Y;    // All A bits less than B (assuming Y is correct)

endmodule

